      .then((me) => {
        setWorkspace(pickWorkspace(me));
        setSession({ state: 'in', me });
      })
      .catch((err) => setSession({ state: err instanceof ApiError && err.status === 401 ? 'out' : 'error' }));
  }, []);

  function chooseWorkspace(id: string) {
    localStorage.setItem(STORAGE_KEY, id);
    setWorkspace(id);
