        const known = new Set(current.map((m) => `${m.direction}:${m.id}`));
        return [...page.messages.filter((m) => !known.has(`${m.direction}:${m.id}`)), ...current];
      });
      setOlder(page.older);
    } catch (err) {
      setError(errorText(err));
    }
  }

  useLayoutEffect(() => {
    const el = scroller.current;
