    }
  }

  const closed = conversation?.status === 'closed';

  return (
    <section className="thread" aria-label={`Conversation with ${contact}`}>
      <ThreadHeader
        contact={contact}
        conversation={conversation}
        meSub={me.sub}
        isAdmin={isAdmin}
        busy={busy}
        onClaim={() => act('claim')}
        onRelease={() => act('release')}
